constraints:
1<=N,K<=10^{6}
-10^{5}<=A[i]<=10^{5}

expected time complexity: O(N).
expected auxiliary space: O(N).

standard_solution_code:
class Solution:

	def longSubarrWthSumDivByK(self, arr, n, K):
		(t, m, d) = (0, 0, dict())
		for i in range(n):
			t += arr[i]
			if t % K == 0:
				m = max(m, i + 1)
			if t % K in d:
				m = max(m, i - d[t % K])
			else:
				d[t % K] = i
		return m
